package com.vandorlabs.neoforge.light;
import com.google.gson.*;
import java.nio.file.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.item.context.*;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.block.state.properties.Half;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Actual configured item preflight, transaction faults, mining and saved recovery. Private bindings only. */
@EventBusSubscriber(modid="vandorlabs")
public final class LightItemChecks {
 private static final BlockPos BASE=new BlockPos(6804,90,6804),SAVE=BASE.east(8);private static final Fixture[] BLOCKS=new Fixture[3];private static final FaultItem[] ITEMS=new FaultItem[3];private static BlockEntityType<NativeLightEntity> TYPE;private static int checks,fault,drops;private static ItemStack dropped=ItemStack.EMPTY;private static BlockPos faultPos,dropPos;
 private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}private static boolean enabled(){return phase().startsWith("light-item-");}private static void need(boolean value,String text){checks++;if(!value)throw new AssertionError("Light item: "+text);}
 private static final class Fixture extends NativeLightBlock {Fixture(int family){super(Kind.values()[family],BlockBehaviour.Properties.of().strength(2.5F).requiresCorrectToolForDrops(),()->TYPE);}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> b){b.add(FACING,HALF);}@Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return (fault==5||fault==6)&&pos.equals(faultPos)?null:super.newBlockEntity(pos,state);}}
 private static final class FaultItem extends NativeLightItem {FaultItem(Fixture block){super(block,new Item.Properties());}@Override protected boolean stage(Level world,BlockPos pos,BlockState state){if(fault==1)return false;boolean changed=super.stage(world,pos,state);if(fault==3)throw new IllegalStateException("fixture after staged Light");return fault==2||fault==4||fault==6?false:changed;}@Override protected boolean restore(Level world,BlockPos pos,BlockState old){return fault==4||fault==6?false:super.restore(world,pos,old);}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent e){if(!enabled())return;e.register(Registries.BLOCK,h->{for(int i=0;i<3;i++){BLOCKS[i]=new Fixture(i);h.register(id(i),BLOCKS[i]);}});e.register(Registries.ITEM,h->{for(int i=0;i<3;i++){ITEMS[i]=new FaultItem(BLOCKS[i]);h.register(id(i),ITEMS[i]);}});e.register(Registries.BLOCK_ENTITY_TYPE,h->{TYPE=BlockEntityType.Builder.<NativeLightEntity>of((p,s)->new NativeLightEntity(TYPE,p,s,com.vandorlabs.neoforge.screen.NativeScreenCatalog.INSTANCE),BLOCKS).build(null);h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","light_item_fixture"),TYPE);});}}
 private static ResourceLocation id(int i){return ResourceLocation.fromNamespaceAndPath("vandorlabs","light_item_fixture_"+i);}
 @SubscribeEvent public static void joined(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent e){if(enabled()&&dropPos!=null&&e.getEntity() instanceof ItemEntity item&&item.position().distanceToSqr(Vec3.atCenterOf(dropPos))<16&&item.getItem().getItem() instanceof NativeLightItem){drops+=item.getItem().getCount();dropped=item.getItem().copy();}}
 private static NativeLightEntity host(ServerLevel world,BlockPos pos){return world.getBlockEntity(pos) instanceof NativeLightEntity owner?owner:null;}
 private static ItemStack configured(int family,CompoundTag tag){var stack=new ItemStack(ITEMS[family],2);var root=new CompoundTag();root.put(NativeLightItem.CONFIGURATION,tag.copy());stack.set(DataComponents.CUSTOM_DATA,CustomData.of(root));return stack;}
 private static void clear(ServerLevel world,BlockPos pos){fault=0;world.getChunkAt(pos);for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)world.setBlock(pos.offset(x,y,z),Blocks.AIR.defaultBlockState(),18);world.setBlock(pos.below(),Blocks.STONE.defaultBlockState(),18);for(var item:world.getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(4)))item.discard();}
 private static InteractionResult place(ServerLevel world,ServerPlayer actor,BlockPos pos,ItemStack stack){actor.setPos(pos.getX()+.5,pos.getY()+1,pos.getZ()-2);actor.setItemInHand(InteractionHand.MAIN_HAND,stack);return stack.useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atBottomCenterOf(pos),Direction.UP,pos.below(),false)));}
 private static void replay(ServerLevel world,ServerPlayer actor)throws Exception{int rows=0;try(var lines=Files.lines(Path.of(System.getProperty("vandorlabs.lightPlacementReference","../../build/test-artifacts/light-placement-forge.jsonl")))){for(String line:(Iterable<String>)lines::iterator){var row=JsonParser.parseString(line).getAsJsonObject();int family=row.get("family").getAsInt();var block=BLOCKS[family];var stack=new ItemStack(ITEMS[family]);var input=row.get("input").getAsString();CompoundTag raw=input.isEmpty()?null:TagParser.parseTag(input);actor.setXRot(row.get("pitch").getAsFloat());actor.setYRot(row.get("yaw").getAsInt()*90);var side=Direction.from3DDataValue(row.get("side").getAsInt());var context=new BlockPlaceContext(world,actor,InteractionHand.MAIN_HAND,stack,new BlockHitResult(new Vec3(BASE.getX()+.2,BASE.getY()+row.get("hit").getAsDouble(),BASE.getZ()+.8),side,BASE,false));var state=block.getStateForPlacement(context);need(state.getValue(NativeLightBlock.FACING).get3DDataValue()==row.get("facing").getAsInt()&&(family!=2||state.getValue(NativeLightBlock.HALF)==(row.get("upper").getAsBoolean()?Half.TOP:Half.BOTTOM)),"actual Source placement state row="+rows);var prepared=NativeLightEntity.prepareItem(TYPE,BASE,state,raw,world.registryAccess());var owner=new NativeLightEntity(TYPE,BASE,state,com.vandorlabs.neoforge.screen.NativeScreenCatalog.INSTANCE);owner.installItem(prepared);var actual=owner.itemSettings();var expected=TagParser.parseTag(row.get("pick").getAsString());for(String key:new String[]{"LightTexture","LightFaceTexture","LightOffFaceTexture","LightLevel","SignalBrightness","LightOffset","LightOn","LightJoin","LightTrigger","housingTexture","HousingTextureVersion","smallInput","framed","GlassShade","GlassTint","GlassMaterial","GlassTextureLayout","RedstoneChannels"})need(java.util.Objects.equals(actual.get(key),expected.get(key)),"source configured projection row="+rows+" key="+key+" expected="+expected.get(key)+" actual="+actual.get(key));need(!actual.contains("ChannelLevel")&&!actual.contains("JoinedSignalLevel"),"item runtime excluded");rows++;}}need(rows==4320,"source configured placement coverage");}
 private static CompoundTag choice(){var tag=new CompoundTag();tag.putInt("LightLevel",6);tag.putBoolean("LightOn",false);tag.putInt("housingTexture",14);tag.putString("FutureLightChoice","opaque:choice");return tag;}
 private static void write(ServerLevel world)throws Exception{var actor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(new java.util.UUID(0,273),"LightItem"));actor.setGameMode(GameType.SURVIVAL);clear(world,BASE);replay(world,actor);actor.setXRot(0);actor.setYRot(0);
  for(int family=0;family<3;family++){clear(world,BASE);var stack=configured(family,choice());need(place(world,actor,BASE,stack).consumesAction()&&stack.getCount()==1,"configured placement consumes one family="+family);var owner=host(world,BASE);need(!owner.inert()&&!owner.visual().on()&&owner.settings().light().configuredLevel==6,"complete selected Light choices installed");var picked=BLOCKS[family].getCloneItemStack(world.getBlockState(BASE),new BlockHitResult(Vec3.atCenterOf(BASE),Direction.NORTH,BASE,false),world,BASE,actor);need(NativeLightItem.configuration(picked).getString("FutureLightChoice").equals("opaque:choice"),"pick preserves opaque choice");for(boolean correct:new boolean[]{false,true}){if(host(world,BASE)==null){stack=configured(family,choice());place(world,actor,BASE,stack);}actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(correct?Items.STONE_PICKAXE:Items.WOODEN_PICKAXE));need(world.getBlockState(BASE).canHarvestBlock(world,BASE,actor)==correct,"actual proper/wrong tool");dropPos=BASE;drops=0;need(actor.gameMode.destroyBlock(BASE)&&drops==(correct?1:0),"proper/wrong tool drops once family="+family);if(correct){var settings=NativeLightItem.configuration(dropped);need(settings.getInt("LightLevel")==6&&settings.getString("FutureLightChoice").equals("opaque:choice"),"harvest uses captured removed tile configuration");}dropPos=null;}}
  for(int mode=1;mode<=6;mode++){clear(world,BASE);fault=mode;faultPos=BASE;var stack=configured(0,choice());boolean threw=false;try{place(world,actor,BASE,stack);}catch(RuntimeException expected){threw=true;}finally{fault=0;}if(mode==4||mode==6){var owner=host(world,BASE);need(threw&&stack.getCount()==1&&owner!=null&&owner.inert(),"failed rollback retains consumed single world owner mode="+mode);need(owner.saveWithoutMetadata(world.registryAccess()).getBoolean(NativeLightItem.PLACEMENT_RECOVERY),"recovery marker persists");}else need(stack.getCount()==2&&world.getBlockState(BASE).isAir(),"stage/factory failure restores old cell and stack mode="+mode);}
  for(int mode=0;mode<3;mode++){clear(world,BASE);var bad=choice();if(mode==0){var reader=new CompoundTag();reader.putString("UnknownOwner","opaque:reader");bad.put("ScreenChipReader",reader);}else if(mode==1)bad.putInt("NativeLightSchema",99);else{var forge=new CompoundTag();forge.putString("VandorTransmitters","opaque:future-module");bad.put("ForgeData",forge);}var stack=configured(0,bad);need(!place(world,actor,BASE,stack).consumesAction()&&stack.getCount()==2&&world.getBlockState(BASE).isAir(),"unsupported ownership rejected before mutation mode="+mode);}
  for(boolean creative:new boolean[]{false,true})for(boolean correct:new boolean[]{false,true}){clear(world,BASE);world.setBlock(BASE,BLOCKS[0].defaultBlockState(),18);var bad=choice();bad.putInt("NativeLightSchema",99);host(world,BASE).loadWithComponents(bad,world.registryAccess());actor.setGameMode(creative?GameType.CREATIVE:GameType.SURVIVAL);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(correct?Items.STONE_PICKAXE:Items.WOODEN_PICKAXE));dropPos=BASE;drops=0;need(actor.gameMode.destroyBlock(BASE)&&drops==1,"inert recovery single item creative="+creative+" correct="+correct);need(NativeLightItem.configuration(dropped).getCompound(NativeLightItem.RECOVERY).getInt("NativeLightSchema")==99,"mined recovery retains exact future schema");dropPos=null;}
  actor.setGameMode(GameType.SURVIVAL);clear(world,BASE);var menuStack=configured(1,choice());need(place(world,actor,BASE,menuStack).consumesAction(),"menu fixture placed");LightMenuChecks.run(host(world,BASE),actor);
  clear(world,SAVE);actor.setGameMode(GameType.SURVIVAL);fault=4;faultPos=SAVE;var stack=configured(0,choice());try{place(world,actor,SAVE,stack);}catch(RuntimeException expected){}finally{fault=0;}need(stack.getCount()==1&&host(world,SAVE).inert(),"saved rollback owner consumes once");world.setChunkForced(SAVE.getX()>>4,SAVE.getZ()>>4,true);
 }
 private static void read(ServerLevel world){world.getChunkAt(SAVE);var owner=host(world,SAVE);need(owner!=null&&owner.inert()&&owner.saveWithoutMetadata(world.registryAccess()).getBoolean(NativeLightItem.PLACEMENT_RECOVERY),"saved failed rollback remains inert after process restart");var picked=NativeLightItem.pick(ITEMS[0],owner);var recovery=NativeLightItem.configuration(picked);need(recovery.getCompound(NativeLightItem.RECOVERY).getString("FutureLightChoice").equals("opaque:choice"),"restart recovery item retains opaque choices");var actor=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(new java.util.UUID(0,274),"LightRecovery"));actor.setGameMode(GameType.SURVIVAL);clear(world,BASE);need(!place(world,actor,BASE,picked).consumesAction()&&picked.getCount()==1&&world.getBlockState(BASE).isAir(),"opaque recovery item cannot silently become a live replacement");}
 @SubscribeEvent public static void started(ServerStartedEvent event)throws Exception{if(!enabled())return;var world=event.getServer().overworld();if(phase().endsWith("write"))write(world);else read(world);event.getServer().saveEverything(true,true,true);System.out.println("[vandorlabs][light-item] "+(phase().endsWith("write")?"write":"read")+" PASS checks="+checks);event.getServer().halt(false);}
}
